  const renderQuiz=()=>{const q=quiz[state.quiz.current],recovery=state.quiz.recovery;$("#masteryCount").textContent=`${state.quiz.mastered.length} / 16 nuclei`;$("#masteryBar").style.width=`${state.quiz.mastered.length/16*100}%`;$("#quizNav").innerHTML=quiz.map((x,i)=>`<button type="button" data-q="${i}" class="${i===state.quiz.current?'current':''} ${state.quiz.mastered.includes(i)?'mastered':''}" aria-label="Nucleo ${i+1}: ${x[0]}${state.quiz.mastered.includes(i)?', compreso':''}">${i+1}</button>`).join('');$$('[data-q]',$("#quizNav")).forEach(b=>b.addEventListener('click',()=>{state.quiz.current=Number(b.dataset.q);state.quiz.recovery=false;save();renderQuiz();}));const question=recovery?q[6]:q[1],options=recovery?q[7]:q[2];$("#quizCard").innerHTML=`<p class="kicker">Nucleo ${state.quiz.current+1} · ${q[0]}${recovery?' · recupero':''}</p><h3>${question}</h3><div class="quiz-options">${options.map((o,i)=>`<button type="button" data-answer="${i}">${o}</button>`).join('')}</div><div id="quizFeedback" aria-live="polite"></div>`;$$('[data-answer]',$("#quizCard")).forEach(b=>b.addEventListener('click',()=>answerQuiz(Number(b.dataset.answer))));$("#quizComplete").hidden=state.quiz.mastered.length!==16;};
