  function buildSynthesis(){const facts=[];if(state.markers.length)facts.push(`hai osservato ${state.markers.length} elementi dell’opera iniziale`);if(JSON.stringify(state.operation)!==JSON.stringify(operationDefaults))facts.push("hai ricontestualizzato un’operazione visiva");if(state.timeline)facts.push(`hai aperto il nodo cronologico ${state.timeline}`);const concepts=conceptRows.filter((r,i)=>state.concepts[i]===r[1]).length;if(concepts)facts.push(`hai classificato correttamente ${concepts} concetti politici`);if(state.condition)facts.push(`hai esplorato la condizione “${state.condition}”`);if(state.apparatus)facts.push(`hai interrogato il nodo “${state.apparatus}” dell’apparato`);if(JSON.stringify(state.context)!==JSON.stringify(contextDefaults))facts.push("hai modificato scala, ripetizione o contesto dell’immagine");if(state.italy)facts.push(`hai confrontato il linguaggio “${state.italy}” nell’Italia fascista`);if(JSON.stringify(state.display)!==JSON.stringify(displayDefaults))facts.push("hai modificato un allestimento astratto");if(state.soviet.length)facts.push(`hai attraversato ${state.soviet.length} trasformazioni della cultura sovietica`);if(state.photo)facts.push(`hai distinto l’operazione fotografica “${state.photo}”`);if(JSON.stringify(state.space)!==JSON.stringify(spaceDefaults))facts.push("hai regolato lo spazio politico");if(JSON.stringify(state.montage)!==JSON.stringify(montageDefaults))facts.push("hai modificato inquadratura o montaggio");const body=bodyRows.filter((r,i)=>state.body[i]===r[1]).length;if(body)facts.push(`hai distinto ${body} livelli del corpo normativo`);if(state.artist)facts.push(`hai analizzato il caso ${artistData[state.artist].title.split(' · ')[0]}`);const evidence=evidenceRows.filter((r,i)=>state.evidence[i]===r[1]).length;if(evidence)facts.push(`hai classificato correttamente ${evidence} tipi di fonte`);if(state.quiz.mastered.length)facts.push(`hai compreso ${state.quiz.mastered.length} nuclei della verifica`);let text=facts.length?`Nel percorso ${facts.join('; ')}. `:"Hai visitato il modulo senza completare ancora attività registrate. ";if(state.notes.initial.trim())text+="Hai scritto una prima ipotesi. ";if(state.notes.final.trim())text+="Hai formulato una seconda lettura. ";text+="Questa sintesi registra azioni e testi: non attribuisce emozioni, opinioni o intenzioni.";$("#personalSynthesis").textContent=text;}
  $("#buildSynthesis").addEventListener('click',buildSynthesis);buildSynthesis();renderQuiz();
